"""DejaVu Serif glyph bitmaps, compressed.

Glyph data rendered from the system DejaVu Serif TTFs with PIL at build time.
Stored zlib-compressed + base64 so the file stays small; main.py needs no Pillow.
Format after decoding: FONTS[(weight, size)][char] = (w, h, yoff, rows, adv)
rows: list of ints, bit-packed MSB-first per row.
"""
import base64
import pickle
import zlib

_BLOB = (
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
)

FONTS = pickle.loads(zlib.decompress(base64.b64decode("".join(_BLOB))))
